def _seed_builtin_poses() -> None:
    """Built-in pose library (FR-020); fixed ids, no project."""
    from datetime import UTC, datetime

    from asset_studio.modules.poses.builtin import ASPECT, BUILTIN_POSES

    pose = sa.table(
        "pose",
        sa.column("id", sa.UUID()),
        sa.column("project_id", sa.UUID()),
        sa.column("name", sa.String()),
        sa.column("view", sa.String()),
        sa.column("aspect", sa.Float()),
        sa.column("keypoints", postgresql.JSONB()),
        sa.column("source", sa.String()),
        sa.column("created_at", sa.DateTime(timezone=True)),
        sa.column("updated_at", sa.DateTime(timezone=True)),
    )
    now = datetime.now(UTC)
    op.bulk_insert(
        pose,
        [
            {
                "id": p.id,
                "project_id": None,
                "name": p.name,
                "view": p.view,
                "aspect": ASPECT,
                "keypoints": [None if k is None else list(k) for k in p.keypoints],
                "source": "library",
                "created_at": now,
                "updated_at": now,
            }
            for p in BUILTIN_POSES
        ],
    )


